describe('Table Row Highlight on Hover', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.get('table').should('be.visible');
  });

  it('should highlight a row when hovering over it', () => {
    cy.get('table tbody tr').first().as('firstRow');

    cy.get('@firstRow').should('not.have.class', 'highlighted');

    cy.get('@firstRow').trigger('mouseenter');

    cy.get('@firstRow').should('have.class', 'highlighted');
    cy.get('@firstRow').should('have.css', 'background-color').and('not.equal', 'rgba(0, 0, 0, 0)');
  });

  it('should remove highlight when mouse leaves the row', () => {
    cy.get('table tbody tr').first().as('firstRow');

    cy.get('@firstRow').trigger('mouseenter');
    cy.get('@firstRow').should('have.class', 'highlighted');

    cy.get('@firstRow').trigger('mouseleave');
    cy.get('@firstRow').should('not.have.class', 'highlighted');
  });

  it('should highlight only the hovered row and not affect other rows', () => {
    cy.get('table tbody tr').eq(0).as('firstRow');
    cy.get('table tbody tr').eq(1).as('secondRow');

    cy.get('@firstRow').trigger('mouseenter');

    cy.get('@firstRow').should('have.class', 'highlighted');
    cy.get('@secondRow').should('not.have.class', 'highlighted');

    cy.get('@firstRow').trigger('mouseleave');
    cy.get('@secondRow').trigger('mouseenter');

    cy.get('@firstRow').should('not.have.class', 'highlighted');
    cy.get('@secondRow').should('have.class', 'highlighted');
  });

  it('should handle rapid hover transitions between rows', () => {
    cy.get('table tbody tr').eq(0).as('firstRow');
    cy.get('table tbody tr').eq(1).as('secondRow');
    cy.get('table tbody tr').eq(2).as('thirdRow');

    cy.get('@firstRow').trigger('mouseenter');
    cy.get('@firstRow').should('have.class', 'highlighted');

    cy.get('@secondRow').trigger('mouseenter');
    cy.get('@firstRow').should('not.have.class', 'highlighted');
    cy.get('@secondRow').should('have.class', 'highlighted');

    cy.get('@thirdRow').trigger('mouseenter');
    cy.get('@secondRow').should('not.have.class', 'highlighted');
    cy.get('@thirdRow').should('have.class', 'highlighted');
  });
});
